"""Reusable conversions for Meridian CRM legacy storage conventions."""

from decimal import Decimal, ROUND_HALF_UP


def to_iso(yyyymmdd: str | None) -> str | None:
    """Convert a legacy YYYYMMDD date to ISO YYYY-MM-DD, preserving null semantics."""
    if yyyymmdd in (None, "", "00000000"):
        return None
    return f"{yyyymmdd[:4]}-{yyyymmdd[4:6]}-{yyyymmdd[6:8]}"


def from_iso(iso: str | None) -> str:
    """Convert an ISO YYYY-MM-DD date to legacy YYYYMMDD sentinel representation."""
    if iso in (None, ""):
        return "00000000"
    return f"{iso[:4]}{iso[5:7]}{iso[8:10]}"


def yn(char: str | None) -> bool:
    """Convert a legacy Y/N/blank boolean to Python bool."""
    return char == "Y"


def to_minor_units(amount, currency: str | None) -> int:
    """Convert a legacy decimal amount to currency minor units using half-up rounding."""
    if amount in (None, ""):
        return 0

    effective_currency = "USD" if currency in (None, "") else currency
    exponent = 0 if effective_currency == "JPY" else 2
    scale = Decimal(10) ** exponent

    decimal_amount = Decimal(str(amount))
    return int((decimal_amount * scale).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
